package com.vynedam.stockai.controller; import com.vynedam.stockai.dto.OperationsDtos.*; import com.vynedam.stockai.model.PurchaseOrder; import com.vynedam.stockai.security.CurrentUser; import com.vynedam.stockai.service.PurchaseOrderService; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1/purchase-orders")public class PurchaseOrderController{private final PurchaseOrderService s;private final CurrentUser u;public PurchaseOrderController(PurchaseOrderService x,CurrentUser y){s=x;u=y;}@GetMapping List<PurchaseOrder>list(){return s.list();}@PostMapping@PreAuthorize("hasAnyRole('SUPER_ADMIN','PURCHASE_MANAGER')")ResponseEntity<PurchaseOrder>create(@Valid@RequestBody PurchaseOrderRequest r,Authentication a){return ResponseEntity.status(201).body(s.create(r,u.id(a)));}@PatchMapping("/{id}/status")@PreAuthorize("hasAnyRole('SUPER_ADMIN','PURCHASE_MANAGER')")PurchaseOrder status(@PathVariable String id,@Valid@RequestBody PurchaseOrderStatusRequest r){return s.status(id,r.status());}}
